 static int cases,validations,captures,frames,waits;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}static void put(Object o,String k,Object v){SourceBatchTerminalPlan.put(o,k,v);}static Object state(ClientSession pc){return SourceElementTransportPlan.state(pc);}
