 @SuppressWarnings("unchecked")static Object queue(Fixture f,byte[] packet)throws Exception{var local=NativeAreaMaterialAction.current;var old=local.get();var light=SourceNpcHpOutputPlan.batches();var oldBatch=light.get();var batch=SourceNpcHpOutputPlan.batch(f.base().caster());var lock=f.base().caster().nativePlayerActionLock();lock.lock();try{local.set(f.c());light.set(batch);check(NativeWeaponBreakTargetLifecycle.captureOutput(f.base().viewer(),packet,"detached actual target output"),"original target captureOutput consumes phase2 output");var outputs=(List<Object>)CombatAccess.field(batch,"outputs");check(outputs.size()==1,"one original weapon-target Batch task");var task=outputs.get(0);outputs.clear();captures++;return task;}finally{lock.unlock();if(old==null)local.remove();else local.set(old);if(oldBatch==null)light.remove();else light.set(oldBatch);}}
 static void run(Object task)throws Exception{SourceElementTransportPlan.run(task);}
 static void reject(Fixture f,Object task,String why)throws Exception{var socket=SourceNpcHpOutputPlan.io(f.base().viewer());long cipher=((Protocol.CipherState)CombatAccess.field(f.base().viewer(),"outgoing")).value();var old=NativeAreaMaterialAction.current.get();run(task);check(socket.bytes.size()==0&&((Protocol.CipherState)CombatAccess.field(f.base().viewer(),"outgoing")).value()==cipher&&NativeAreaMaterialAction.current.get()==old,"original target output rejects before cipher without changing parent Context "+why);}
 static void waitReject(Fixture f,Object task,Object monitor,Runnable mutation,String why)throws Exception{var socket=SourceNpcHpOutputPlan.io(f.base().viewer());long cipher=((Protocol.CipherState)CombatAccess.field(f.base().viewer(),"outgoing")).value();var began=new CountDownLatch(1);var failure=new AtomicReference<Throwable>();var worker=new Thread(()->{try{began.countDown();run(task);}catch(Throwable e){failure.set(e);}},"target-output-original-Hub-population-wait");synchronized(monitor){worker.start();check(began.await(3,TimeUnit.SECONDS),"target worker started");SourceElementAudiencePlan.blocked(worker,"original Hub/population output wait "+why);check(!f.base().viewer().nativePlayerActionLock().isLocked(),"original callback has released receiver action lock before Hub/population output wait");mutation.run();}worker.join(3000);check(!worker.isAlive()&&failure.get()==null&&socket.bytes.size()==0&&((Protocol.CipherState)CombatAccess.field(f.base().viewer(),"outgoing")).value()==cipher,"original output refuses retired proof after original monitor wait "+why);waits++;}
 static void output(String phase,boolean population)throws Exception{var f=fixture(phase,population);var b=f.base();byte[] packet=Protocol.effectObject(b.target().playerObjectId(),44);var task=queue(f,packet);var socket=SourceNpcHpOutputPlan.io(b.viewer());run(task);check(socket.bytes.size()==packet.length+2,"actual original capture/task/permit/Hub/population/send/final cipher positive "+phase+"/"+population);frames++;
  Object receiverState=state(b.viewer()),receiverOwner=CombatAccess.field(receiverState,"sourcePlayerOwner"),subjectState=state(b.target()),subjectOwner=CombatAccess.field(subjectState,"sourcePlayerOwner"),subjectStatus=CombatAccess.field(b.target(),"timedStatus");task=queue(f,packet);CombatAccess.set(receiverState,"sourcePlayerOwner",null);reject(f,task,"receiver owner removed before player-lock stage");check(CombatAccess.field(receiverState,"sourcePlayerOwner")==null,"original receiver Task does not recreate owner");CombatAccess.set(receiverState,"sourcePlayerOwner",receiverOwner);
  task=queue(f,packet);CombatAccess.set(subjectState,"sourcePlayerOwner",null);reject(f,task,"packet subject owner removed before Context.player stream");check(CombatAccess.field(subjectState,"sourcePlayerOwner")==null,"original subject validation does not recreate owner");CombatAccess.set(subjectState,"sourcePlayerOwner",subjectOwner);
  task=queue(f,packet);CombatAccess.set(subjectStatus,"sourcePoisonLifecycle",null);reject(f,task,"packet subject lifecycle removed");check(CombatAccess.field(subjectStatus,"sourcePoisonLifecycle")==null,"original Context subject path does not recreate lifecycle");CombatAccess.set(subjectStatus,"sourcePoisonLifecycle",subjectState);
  task=queue(f,packet);waitReject(f,task,b.hub(),()->CombatAccess.set(receiverState,"sourcePlayerOwner",null),"receiver original owner cleared at Hub wait");check(CombatAccess.field(receiverState,"sourcePlayerOwner")==null,"Hub wait callback never rebinds receiver role");CombatAccess.set(receiverState,"sourcePlayerOwner",receiverOwner);
  if(population){task=queue(f,packet);waitReject(f,task,f.population(),()->CombatAccess.set(subjectState,"sourcePlayerOwner",null),"subject original owner cleared at population wait");check(CombatAccess.field(subjectState,"sourcePlayerOwner")==null,"population wait retains missing subject role");CombatAccess.set(subjectState,"sourcePlayerOwner",subjectOwner);}
  task=queue(f,packet);waitReject(f,task,b.hub(),()->{NativePlayerCommit.scene(b.viewer(),2L,"currentRoomId");NativePlayerCommit.scene(b.viewer(),1L,"currentRoomId");},"actual receiver scene ABA");
 }
 public static void main(String[]args)throws Exception{var area=NativeAreaMaterialAction.current;var oldArea=area.get();var frame=SourceNpcHpOutputPlan.frames();var oldFrame=frame.get();var light=SourceNpcHpOutputPlan.batches();var oldBatch=light.get();var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);var oldRules=rules.get(null);var controls=NativeSourceOtherControls.class.getDeclaredField("current");controls.setAccessible(true);var oldControls=controls.get(null);try{area.remove();frame.remove();light.remove();var path=java.nio.file.Path.of("detached-Context-output-readonly-role-no-Source-reader");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));var props=new Properties();props.setProperty("hpbar","true");controls.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(props),path));for(String phase:List.of("BATTLE","WORLD")){validators(phase);for(boolean population:List.of(false,true))output(phase,population);}check(validations==12&&captures==26&&frames==4&&waits==10,"BATTLE/WORLD and both original population branches exercise original validation/output waits");}finally{if(oldArea==null)area.remove();else area.set(oldArea);if(oldFrame==null)frame.remove();else frame.set(oldFrame);if(oldBatch==null)light.remove();else light.set(oldBatch);rules.set(null,oldRules);controls.set(null,oldControls);}check(area.get()==oldArea&&frame.get()==oldFrame&&light.get()==oldBatch&&rules.get(null)==oldRules,"all original TLS/rules/controls restored");System.out.println("PASS"+cases+" Context readonly-role original-scene/player/target-output contracts; validation-removals="+validations+", original-captures="+captures+", memory-frames="+frames+", original-Hub-population-waits="+waits+"; full earlier selection/HP/cancel/reentrant/Main/Source/backend/memory/game/MySQL remain open");}
